import{_ as t,o,c as u,ag as q}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第67章 十九分钟","description":"","frontmatter":{},"headers":[],"relativePath":"第67章_十九分钟.md","filePath":"第67章_十九分钟.md"}'),e={name:"第67章_十九分钟.md"};function a(_,p,r,n,s,c){return o(),u("div",null,[...p[0]||(p[0]=[q('<h1 id="第67章-十九分钟" tabindex="-1">第67章 十九分钟 <a class="header-anchor" href="#第67章-十九分钟" aria-label="Permalink to &quot;第67章 十九分钟&quot;">​</a></h1><p>我们第一次正经语音，是在六月中。</p><p>在那之前，我只听见过她两次声音。</p><p>一次是高二，她发了一条三秒的语音，第二天撤回了。</p><p>那次我什么也没听见，只有底噪，很响的一片沙沙声，中间有一个很短的吸气。</p><p>我把那三秒听了一晚上。</p><p>后来那条撤回，我这边也点不开了。</p><p>第二次是高三，四分钟。</p><p>那次电话是我从一个朋友那儿借的，他站在旁边等，他的手在膝盖上敲。</p><p>那四分钟里我们说的是&quot;你那边几点&quot;&quot;你在干什么&quot;&quot;你妈在旁边吗&quot;。</p><p>一次也没有安静过，因为我一安静，我就听见他手指敲膝盖的声音，我就要挂。</p><p>第三次就是六月那次。</p><p>那次是我们约好的。</p><p>我提前两天开始准备。</p><p>我在宿舍里开了一个&quot;会&quot;。</p><p>我们六个人，那天晚上我买了两袋橘子回来，我把袋子放在中间，我说我今晚要打个电话，很长，可能一个多小时，我请你们小点声。</p><p>郑拓说，多大一个电话。</p><p>我说，可能一小时。</p><p>他说，那我跟你说，我们十一点半要打一把。</p><p>我说，我十二点前挂。</p><p>他说，那你最好十二点前挂。</p><p>上铺那个人说，你打电话我们听你的还是听我们自己的。</p><p>我说，对不起。</p><p>他说，你道什么歉，你说时间就行。</p><p>那天下午我做了一件很蠢的事。</p><p>我拿了一条毛巾，塞在门底下。</p><p>因为走廊的灯和人声会进来。</p><p>我又把我那个台灯挪了，挪到不能照到别人眼睛的位置。</p><p>六点，我们宿舍只剩三个人，另外两个回家了。</p><p>七点五十，我戴上耳塞。</p><p>不是听她用的，是给她用的——我怕我的呼噜、我的呼吸被别人听见。</p><p>八点整，我按了拨出去。</p><p>响了两声，接通了。</p><p>我先听见的不是她。</p><p>是一台冰箱。</p><p>很远的、嗡嗡的一台冰箱，在那一段声音底上铺着。</p><p>然后有门响了一下，有人说话，说的不是中文。</p><p>然后是她。</p><p>她说，喂。</p><p>我说，喂。</p><p>她说，你怎么不说话。</p><p>我说，我在听。</p><p>她说，你听什么。</p><p>我说，你那边有冰箱。</p><p>她那边静了一下。</p><p>然后她说，哦，那是厨房的。</p><p>她说，我这里这个冰箱坏过两次，制冷的时候声音很大。</p><p>我说，我以为是我这边的问题。</p><p>她说，你那边怎么了。</p><p>我说，我这边很安静。</p><p>她说，你宿舍就你一个？</p><p>我说，还有两个，回家了。</p><p>她说，那你别在走廊。</p><p>我说，我在屋里，我把门缝堵了。</p><p>她笑了。</p><p>她笑的时候声音很短，两下，气比声多。</p><p>那是我第一次知道她笑起来是有气的。</p><p>我们那天说了多久，我记得是十九分钟。</p><p>十九分钟里，我们说的话我数过，我晚上回去默写过一遍。</p><p>我说的：</p><p>喂。</p><p>我在听。</p><p>你那边有冰箱。</p><p>我这边很安静。</p><p>我把门缝堵了。</p><p>你今天吃了什么。</p><p>你嗓子是不是不舒服。</p><p>没有，我没有觉得不好听。</p><p>你说。</p><p>我在。</p><p>好。</p><p>你说的第三件是什么。</p><p>……</p><p>她说的更少。</p><p>她说的：</p><p>喂。</p><p>哦，那是厨房的。</p><p>你宿舍就你一个？</p><p>那你别在走廊。</p><p>我今天吃了饭。</p><p>还行。</p><p>还行。</p><p>你别问。</p><p>我们还是打字吧。</p><p>十九分钟里，她说了三次&quot;还行&quot;。</p><p>我们认识六年，她从不在打字的时候说&quot;还行&quot;。</p><p>她打字的时候会讲很长一段，讲到一个具体的程度：一碗面，面是烂的，汤是咸的，她吃了半碗，剩下的倒了。</p><p>那是她的说话方式。</p><p>语音里没有。</p><p>语音里她只有&quot;还行&quot;&quot;你别问&quot;&quot;我今天吃了饭&quot;。</p><p>我不知道这是什么意思。</p><p>我那天晚上回去，把这三句抄在本子上。</p><p>抄完我在旁边写了一行：</p><p>我写：她在打字的时候可以是她，在出声的时候不能是。</p><p>第五分钟的时候，她那边有人回来了。</p><p>我听见门响，然后是包放在桌上的那一声。</p><p>她那边说了一句别的话，不是中文。</p><p>然后她说，等一下。</p><p>我说，好。</p><p>那一下我等了三分四十秒。</p><p>三分四十秒里，我听见她把手机放下来，听见她在跟人说话，声音压得很低。</p><p>听不清内容。</p><p>我只听见她有一句的尾音是往下掉的。</p><p>那一句她可能在拒绝。</p><p>她回来说，好了。</p><p>我说，你忙完了。</p><p>她说，嗯。</p><p>她说，你别等这个，以后你别等。</p><p>我说，我不等，我挂着。</p><p>她说，你挂着我在你这边是很响的。</p><p>我说，为什么。</p><p>她说，因为你呼吸很重。</p><p>我那天晚上第一次知道，我呼吸很重。</p><p>第十四分钟，她忽然问了一句。</p><p>她说，你是不是觉得我声音不好听。</p><p>我说，没有。</p><p>她说，你刚才顿了一下。</p><p>我说，我在想怎么说。</p><p>她说，你想怎么说就说。</p><p>我说，我觉得跟我以为的不一样。</p><p>她没说话。</p><p>我说，我说的不是坏的意思。</p><p>我说，我一直以为你的声音会高一点。</p><p>她说，高一点是哪种。</p><p>我说，就是……我脑子里那个。</p><p>她说，你脑子里那个是什么。</p><p>我说，是三秒那条。</p><p>她那天晚上最后说的是这句。</p><p>她说，你把那三秒听了很多遍吧。</p><p>我说，一晚上。</p><p>她说，撤回了你还听。</p><p>我说，撤回了就听不了了。</p><p>她说，那你现在听见了。</p><p>我说，嗯。</p><p>她说，你又嗯。</p><p>她说，你就不能一次多说几个字。</p><p>那一秒我很想说：我在你出声的时候，我不敢多说。</p><p>我打的是——我没打字。</p><p>我说了出来。</p><p>我说，因为你今天说话很少，我怕我一多说，你就更不说了。</p><p>那十九分钟里她第一次说了一句长的。</p><p>她说，我今天不是不想说。</p><p>她说，我是怕我说长了，你那边有人会听见。</p><p>她说，我不知道你们这边是不是也有人。</p><p>她说，我昨天问过我室友能不能用阳台打电话，她说可以。</p><p>她说，可是我今天在屋里，因为我今天不舒服。</p><p>她说，所以我不敢说多。</p><p>我说，你现在可以下来，我们这边没人。</p><p>她说，现在不行。</p><p>我说，为什么。</p><p>她说，因为我室友刚回来，她在洗澡。</p><p>她说，我要是再讲话，她要问我跟谁讲。</p><p>她说，我说不出跟谁讲。</p><p>那天我们挂的时候是八点十九。</p><p>挂之前她说了一句。</p><p>她说，我们还是打字吧。</p><p>我说，好。</p><p>挂完那一下，我屋里真的很安静。</p><p>我把耳塞摘了。</p><p>冰箱那个声音我关不掉。</p><p>我把手机放在桌上，等了一下。</p><p>八点二十，屏幕上跳进来一条。</p><p>她说，今天那个汤我其实没吃完。</p><p>八点二十一分，第二条。</p><p>她说，他们那个中餐馆的汤很咸，我要了两碗米饭泡着吃。</p><p>八点二十二，第三条。</p><p>她说，我明天要去修那个冰箱。</p><p>八点二十三分，第四条。</p><p>她说，我今天中午在楼下看见一只猫，跟我以前养的那只有点像。</p><p>八点二十四，第五条。</p><p>那五条我一条一条读完。</p><p>我读得很快。</p><p>因为打字的时候，她又回到她那边下午五点了。</p><p>那天夜里我抄完那三句&quot;还行&quot;，我又做了一件事。</p><p>我把十九分钟里她说过的每一句，按顺序写下来。</p><p>一共十四句。</p><p>写到第七句的时候我停住了。</p><p>因为那十四句里，有六句是问句。</p><p>她那十九分钟里问了我六次。</p><p>而我在打字的那四年里，几乎没问过她什么。</p><p>那天我算出来一件事。</p><p>她在语音里一直在把话递给我。</p><p>她说&quot;你听什么&quot;，她说&quot;你那边怎么了&quot;，她说&quot;你宿舍就你一个&quot;，她说&quot;你挂了我在你这边是很响的&quot;，她说&quot;撤回了你还听&quot;，她说&quot;你就不能一次多说几个字&quot;。</p><p>六句。</p><p>每一句都是我可以说一句长的地方。</p><p>而我六句里回的是&quot;我在听&quot;&quot;我这边很安静&quot;&quot;还有两个&quot;&quot;为什么&quot;&quot;一晚上&quot;&quot;嗯&quot;。</p><p>那天我在那页本子的最底下，写了四个字。</p><p>我写：她递过六次。</p><p>我把本子合上，去洗了澡。</p><p>我们那栋楼的热水管在六月份也有声音。</p><p>我在淋浴底下听那根管子响，忽然想到她那边那台冰箱。</p><p>我这辈子离她最近的一次，是听见了她屋子里一台会坏的冰箱。</p>',192)])])}const l=t(e,[["render",a]]);export{d as __pageData,l as default};
